// Local reference layer for the globe.
// Source: Natural Earth v5.1.2 public domain.
//   1:50m coastline, simplified to about 0.035° and rounded to 0.01°.
//   1:110m river and lake centerlines, simplified to about 0.08°.
//   1:110m populated places with population >= 200,000, plus capitals and world cities.
// Generated by scripts/build-reference-geography.mjs. Names are not stored.
// https://www.naturalearthdata.com/about/terms-of-use/

import geography from './referenceGeography.json' with { type: 'json' }

export interface ReferencePath {
  kind: 'coast' | 'river'
  points: [number, number][]
  color: string
  stroke: number | null
}

export interface ReferenceCity {
  lat: number
  lng: number
}

function asLines(value: unknown): [number, number][][] {
  if (!Array.isArray(value)) return []
  return value.flatMap((line) => {
    if (!Array.isArray(line)) return []
    const points = line.flatMap((point) => {
      if (!Array.isArray(point) || point.length < 2) return []
      const lng = point[0]
      const lat = point[1]
      if (typeof lng !== 'number' || typeof lat !== 'number') return []
      return [[lng, lat] as [number, number]]
    })
    return points.length >= 2 ? [points] : []
  })
}

export const referenceSource = geography.source
export const referenceLicense = geography.license

export const coastPaths: ReferencePath[] = asLines(geography.coast).map((points) => ({
  kind: 'coast',
  points,
  color: '#e7f3fb',
  stroke: null,
}))
export const riverPaths: ReferencePath[] = asLines(geography.rivers).map((points) => ({
  kind: 'river',
  points,
  color: '#9fd6ea',
  stroke: 1.6,
}))
export const regionalPaths: ReferencePath[] = [...coastPaths, ...riverPaths]

export const referenceCities: ReferenceCity[] = geography.cities.flatMap((city) => {
  if (!Array.isArray(city) || city.length < 2) return []
  const lat = city[0]
  const lng = city[1]
  if (typeof lat !== 'number' || typeof lng !== 'number') return []
  return [{ lat, lng }]
})
